import React, { useState, useEffect } from "react";

function SearchPage() {

const [jobs,setJobs] = useState([]);
const [search,setSearch] = useState("");

useEffect(()=>{

fetch("http://localhost:5000/api/jobs")
.then(res=>res.json())
.then(data=>setJobs(data))
.catch(err=>console.log(err));

},[]);


const filteredJobs = jobs.filter(job => {

const title = job.title ? job.title.toLowerCase() : "";
const company = job.company ? job.company.toLowerCase() : "";
const branch = job.branch ? job.branch.join(" ").toLowerCase() : "";

return (
title.includes(search.toLowerCase()) ||
company.includes(search.toLowerCase()) ||
branch.includes(search.toLowerCase())
);

});


return(

<div style={{padding:"40px"}}>

<h1>Search Jobs</h1>

<input
type="text"
placeholder="Search company, job, branch..."
value={search}
onChange={(e)=>setSearch(e.target.value)}
style={{
width:"400px",
padding:"10px",
marginBottom:"20px"
}}
/>


{filteredJobs.map(job => (

<div key={job.jobId}
style={{
border:"1px solid gray",
padding:"15px",
marginBottom:"15px",
borderRadius:"8px"
}}
>

<h3>{job.title || "No Title"}</h3>

<p>Company: {job.company || "Unknown"}</p>

<p>Branch: {job.branch ? job.branch.join(", ") : "All"}</p>

<p>Type: {job.jobType}</p>

<p>Eligible: {job.eligibleYears ? job.eligibleYears.join(", ") : "-"}</p>

<a href={job.applyLink} target="_blank">
Apply
</a>

</div>

))}

</div>

)

}

export default SearchPage;
